From 2d6157687181376933b4622367a0f7faa137c9b4 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:09:11 +0100
Subject: [PATCH] containmentactions/applauncher: add Lock Screen and Show
 Logout Screen

With the desktop's right-click set to the Application Menu there was no
way to lock or leave the session from it, unlike the standard menu. The
menu now ends with the same Lock Screen and Show Logout Screen actions.

BUG: 479281
---
 containmentactions/applauncher/CMakeLists.txt |  4 ++-
 containmentactions/applauncher/launch.cpp     | 32 +++++++++++++++++++
 containmentactions/applauncher/launch.h       |  3 ++
 3 files changed, 38 insertions(+), 1 deletion(-)

diff --git a/containmentactions/applauncher/CMakeLists.txt b/containmentactions/applauncher/CMakeLists.txt
index 4a7d645952..8f855a37e7 100644
--- a/containmentactions/applauncher/CMakeLists.txt
+++ b/containmentactions/applauncher/CMakeLists.txt
@@ -1,5 +1,7 @@
 add_definitions(-DTRANSLATION_DOMAIN=\"plasma_containmentactions_applauncher\")

+include_directories(${plasma-workspace_SOURCE_DIR}/libkworkspace)
+
 set(applauncher_SRCS
     launch.cpp launch.h
 )
@@ -11,4 +13,4 @@ set_target_properties(plasma_containmentactions_applauncher PROPERTIES
     OUTPUT_NAME org.kde.applauncher
 )

-target_link_libraries(plasma_containmentactions_applauncher Plasma::Plasma KF6::KIOCore KF6::KIOWidgets KF6::I18n)
+target_link_libraries(plasma_containmentactions_applauncher Plasma::Plasma KF6::KIOCore KF6::KIOWidgets KF6::I18n PW::KWorkspace)
diff --git a/containmentactions/applauncher/launch.cpp b/containmentactions/applauncher/launch.cpp
index fdef2d999f..937e1c67a6 100644
--- a/containmentactions/applauncher/launch.cpp
+++ b/containmentactions/applauncher/launch.cpp
@@ -8,16 +8,21 @@

 #include <QDebug>

+#include <KAuthorized>
 #include <KConfigGroup>
 #include <KIO/ApplicationLauncherJob>
+#include <KLocalizedString>
 #include <KPluginFactory>
 #include <Plasma/PluginLoader>

+#include <sessionmanagement.h>
+
 using namespace Qt::StringLiterals;

 AppLauncher::AppLauncher(QObject *parent, const QVariantList &args)
     : Plasma::ContainmentActions(parent, args)
     , m_group(new KServiceGroup(QStringLiteral("/")))
+    , m_session(new SessionManagement(this))
 {
 }

@@ -32,6 +37,7 @@ QList<QAction *> AppLauncher::contextualActions()
     qDeleteAll(m_actions);
     m_actions.clear();
     makeMenu(nullptr, m_group);
+    addSessionActions();

     return m_actions;
 }
@@ -83,6 +89,32 @@ void AppLauncher::makeMenu(QMenu *menu, const KServiceGroup::Ptr &group)
     }
 }

+void AppLauncher::addSessionActions()
+{
+    const bool canLock = KAuthorized::authorizeAction(QStringLiteral("lock_screen"));
+    const bool canLogout = KAuthorized::authorize(QStringLiteral("logout"));
+    if (!canLock && !canLogout) {
+        return;
+    }
+
+    auto *separator = new QAction(this);
+    separator->setSeparator(true);
+    m_actions << separator;
+
+    if (canLock) {
+        auto *lockScreenAction = new QAction(QIcon::fromTheme(QStringLiteral("system-lock-screen")), i18n("Lock Screen"), this);
+        lockScreenAction->setEnabled(m_session->canLock());
+        connect(lockScreenAction, &QAction::triggered, m_session, &SessionManagement::lock);
+        m_actions << lockScreenAction;
+    }
+
+    if (canLogout) {
+        auto *logoutAction = new QAction(QIcon::fromTheme(QStringLiteral("system-log-out")), i18n("Show Logout Screen"), this);
+        connect(logoutAction, &QAction::triggered, m_session, &SessionManagement::requestLogoutPrompt);
+        m_actions << logoutAction;
+    }
+}
+
 QWidget *AppLauncher::createConfigurationInterface(QWidget *parent)
 {
     auto *widget = new QWidget(parent);
diff --git a/containmentactions/applauncher/launch.h b/containmentactions/applauncher/launch.h
index c6f4dbf61f..03a9ae9399 100644
--- a/containmentactions/applauncher/launch.h
+++ b/containmentactions/applauncher/launch.h
@@ -15,6 +15,7 @@
 #include "ui_config.h"

 class QAction;
+class SessionManagement;

 class AppLauncher : public Plasma::ContainmentActions
 {
@@ -35,9 +36,11 @@ public:

 protected:
     void makeMenu(QMenu *menu, const KServiceGroup::Ptr &group);
+    void addSessionActions();

 private:
     KServiceGroup::Ptr m_group;
+    SessionManagement *const m_session;
     QList<QAction *> m_actions;

     Ui::Config m_ui;
